def to_12h(minutes):
    hour = minutes // 60
    minute = minutes % 60
    hour12 = hour % 12
    if hour12 == 0:
        hour12 = 12
    suffix = "AM" if hour < 12 else "PM"
    return f"{hour12}:{minute:02d}{suffix}"

