START_TIME = 9 * 60

def build_schedule(order):
    events = [f"You start at {START_LOCATION} at {to_12h(START_TIME)}."]
    current_location = START_LOCATION
    current_time = START_TIME

    for name in order:
        info = FRIENDS[name]
        location = info["location"]
        window_start, window_end = info["window"]
        duration = info["minimum_minutes"]

        if current_location == location:
            travel_time = 0
        else:
            travel_time = TRAVEL_TIMES[(current_location, location)]

        arrival_time = current_time + travel_time
        meeting_start = max(arrival_time, window_start)
        meeting_end = meeting_start + duration

        if meeting_end > window_end:
            return None

        if travel_time > 0:
            events.append(
                f"You travel to {location} in {travel_time} minutes and arrive at {to_12h(arrival_time)}."
            )

        if meeting_start > arrival_time:
            events.append(f"You wait until {to_12h(meeting_start)}.")

        events.append(
            f"You meet {name} for {duration} minutes from {to_12h(meeting_start)} to {to_12h(meeting_end)}."
        )

        current_location = location
        current_time = meeting_end

    return events, current_time

def solve():
    names = list(FRIENDS.keys())
    best_schedule = None
    best_score = None

    for subset_size in range(len(names), 0, -1):
        for combo in combinations(names, subset_size):
            for order in permutations(combo):
                result = build_schedule(order)
                if result is None:
                    continue
                events, end_time = result
                score = (subset_size, -end_time)
                if best_score is None or score > best_score:
                    best_score = score
                    best_schedule = events

        if best_schedule is not None:
            return best_schedule

    return []

if __name__ == "__main__":
