def format_time(minutes):
    hours, mins = divmod(minutes, 60)
    suffix = "AM" if hours < 12 else "PM"
    hour12 = hours % 12
    if hour12 == 0:
        hour12 = 12
    return f"{hour12}:{mins:02d}{suffix}"


def build_schedule(order):
    steps = [("start", START_LOCATION, START_TIME)]
    current_time = START_TIME
    current_location = START_LOCATION

    for name in order:
        friend = FRIENDS[name]
        travel_minutes = TRAVEL_TIMES[(current_location, friend["location"])]
        arrival_time = current_time + travel_minutes

        meet_start = max(arrival_time, friend["start"])
        meet_end = meet_start + friend["duration"]

        if meet_end > friend["end"]:
            return None

        steps.append(("travel", friend["location"], travel_minutes, arrival_time))

        if arrival_time < meet_start:
            steps.append(("wait", meet_start))

        steps.append(("meet", name, meet_start, meet_end, friend["duration"]))

        current_time = meet_end
        current_location = friend["location"]

    return steps


def render(steps):
    lines = []
    for step in steps:
        if step[0] == "start":
            _, location, time = step
            lines.append(f"You start at {location} at {format_time(time)}.")
        elif step[0] == "travel":
            _, location, duration, arrival = step
            lines.append(
                f"You travel to {location} in {duration} minutes and arrive at {format_time(arrival)}."
            )
        elif step[0] == "wait":
            _, time = step
            lines.append(f"You wait until {format_time(time)}.")
        elif step[0] == "meet":
            _, name, start, end, duration = step
            lines.append(
                f"You meet {name} for {duration} minutes from {format_time(start)} to {format_time(end)}."
            )
    return lines


def solve():
    names = list(FRIENDS.keys())
    best_schedule = None
    best_key = None

    for r in range(1, len(names) + 1):
        for subset in combinations(names, r):
            for order in permutations(subset):
                schedule = build_schedule(order)
                if schedule is None:
                    continue

                meetings = [step for step in schedule if step[0] == "meet"]
                if not meetings:
                    continue

                num_met = len(meetings)
                completion_time = meetings[-1][3]
                key = (-num_met, completion_time, order)

                if best_key is None or key < best_key:
                    best_key = key
                    best_schedule = schedule

    return best_schedule


if __name__ == "__main__":
    schedule = solve()
    if schedule is None:
        print([])
    else:
