def to_min(s):
    s = s.strip()
    ampm = s[-2:]
    h, m = map(int, s[:-2].split(":"))
    if ampm == "AM":
        if h == 12:
            h = 0
    else:
        if h != 12:
            h += 12
    return h * 60 + m

