def fmt(t):
    t %= 1440
    h, m = divmod(t, 60)
    period = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{period}"

travel = {
    ("North Beach", "Pacific Heights"): 8,
    ("North Beach", "Embarcadero"): 6,
    ("Pacific Heights", "North Beach"): 9,
    ("Pacific Heights", "Embarcadero"): 10,
    ("Embarcadero", "North Beach"): 5,
    ("Embarcadero", "Pacific Heights"): 11,
}

friends = {
    "Mark": {"loc": "Embarcadero", "start": 13 * 60, "end": 17 * 60 + 45, "min": 120},
    "Karen": {"loc": "Pacific Heights", "start": 18 * 60 + 45, "end": 20 * 60 + 15, "min": 90},
}

best = {"score": (-1, -1), "actions": []}

def dfs(loc, cur_time, met, actions):
    score = (len(met), sum(d for _, d in met))
    if score > best["score"]:
        best["score"] = score
        best["actions"] = actions[:]

    for name, f in friends.items():
        if any(n == name for n, _ in met):
            continue

        dest = f["loc"]
        if loc == dest:
            travel_mins = 0
            arrival_time = cur_time
        else:
            travel_mins = travel[(loc, dest)]
            arrival_time = cur_time + travel_mins

        latest_start = f["end"] - f["min"]
        if arrival_time > latest_start:
            continue

        start_meet = max(arrival_time, f["start"])
        if start_meet > latest_start:
            continue

        max_dur = f["end"] - start_meet
        for dur in range(f["min"], max_dur + 1):
            end_meet = start_meet + dur
            new_actions = actions[:]

            if loc != dest:
                new_actions.append(
                    f"You travel to {dest} in {travel_mins} minutes and arrive at {fmt(arrival_time)}."
                )
            if arrival_time < f["start"]:
                new_actions.append(f"You wait until {fmt(f['start'])}.")
            new_actions.append(
                f"You meet {name} for {dur} minutes from {fmt(start_meet)} to {fmt(end_meet)}."
            )

            dfs(dest, end_meet, met + [(name, dur)], new_actions)

initial = [f"You start at North Beach at {fmt(9 * 60)}."]
dfs("North Beach", 9 * 60, [], initial)
print(best["actions"])
